import json,re
for d in ['candidate-search','candidate-search-healthy']:
    print('=====',d)
    for l in open(d+'/transcript.jsonl',encoding='utf8'):
        for m in re.finditer(r'.{80}recycle.{80}',l,re.I): print('RECYCLE:',m.group(0))
        j=json.loads(l)
        c=j.get('message',{}).get('content')
        if isinstance(c,list):
            for x in c:
                if x.get('type')=='tool_result':
                    t=x['content'] if isinstance(x['content'],str) else json.dumps(x['content'])
                    if t.startswith('V=') or 'Name' in t[:30] or 'True' in t[:20] or '=== raw' in t:
                        print(t[:300] if '=== raw' not in t else t[t.index('=== raw'):][:2500]);print('---')
